import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        details TEXT,
        ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.before_request
def check_api_key():
    key = request.headers.get('X-API-Key')
    if not key:
        return jsonify({'error': 'missing api key'}), 401
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (key,)).fetchone()
    if not user:
        return jsonify({'error': 'invalid api key'}), 403
    g.current_user = dict(user)

@app.route('/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Restrict searchable fields to prevent information disclosure
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    # Build query with field validation above ensuring safety
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        # Log the search for compliance
        db.execute(
            'INSERT INTO audit_log (action, user_id, details) VALUES (?, ?, ?)',
            ('search', g.current_user['id'], f'field={field} q={value}')
        )
        db.commit()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        app.logger.error(f'Search error: {e}')
        return jsonify({'error': 'search failed'}), 500

@app.route('/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/users', methods=['POST'])
def create_user():
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'forbidden'}), 403
    data = request.get_json()
    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, role, api_key) VALUES (?, ?, ?, ?)',
            (data['username'], data['email'], data.get('role', 'user'), os.urandom(16).hex())
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
